export interface DossierOptions {
  text_max_bytes: number;
  screenshots: { max: number; max_bytes: number };
  dashboard: { max_files: number; max_bytes: number };
}

export function buildDossier(outDir: string, opts: DossierOptions): string {
  const dossier = {
    competition: 'token-radar-01',
    generated_at: new Date().toISOString(),
    output_dir: outDir,
    caps: {
      text_max_bytes: opts.text_max_bytes,
      screenshots: opts.screenshots,
      dashboard: opts.dashboard,
    },
    notes: 'Token radar entry — radar board, watchlist farm plans, and dossier generated by Ada Wrong.',
  };
  return JSON.stringify(dossier, null, 2) + '\n';
}
